import { createClient } from "gel";

async function run() {
  const client = createClient();
  try {
    await client.execute(`
      insert Category { name := 'test-cat' } unless conflict on .name else (select Category);
      insert Tag { label := 'tag-a' } unless conflict on .label else (select Tag);
      insert Tag { label := 'tag-b' } unless conflict on .label else (select Tag);
    `);
    await client.execute(`
      insert Product {
        sku := 'sku-test',
        name := 'Test Product',
        price_cents := 500,
        stock := 50,
        category := (select Category filter .name = 'test-cat'),
        tags := (select Tag filter .label in {'tag-a', 'tag-b'})
      } unless conflict on .sku else (
        update Product set {
          tags := (select Tag filter .label in {'tag-a', 'tag-b'})
        }
      );
    `);

    const result = await client.query(`
      select Product {
        sku,
        name,
        price_cents,
